script:
// 示例插件：不联网。搜索返回两段测试音，getMedia 现场合成 WAV 的 data URL。
// 它存在的意义是让你看见整条链路：装插件 → 选音源 → 搜索 → 播放。
function tone(seconds, freq, wobble) {
  var rate = 22050;
  var n = Math.floor(rate * seconds);
  var total = 44 + n;
  var buf = new ArrayBuffer(total);
  var v = new DataView(buf);
  function tag(off, s) { for (var i = 0; i < s.length; i++) v.setUint8(off + i, s.charCodeAt(i)); }
  tag(0, 'RIFF'); v.setUint32(4, total - 8, true); tag(8, 'WAVEfmt ');
  v.setUint32(16, 16, true); v.setUint16(20, 1, true); v.setUint16(22, 1, true);
  v.setUint32(24, rate, true); v.setUint32(28, rate, true);
  v.setUint16(32, 1, true); v.setUint16(34, 8, true);
  tag(36, 'data'); v.setUint32(40, n, true);
  for (var i = 0; i < n; i++) {
    var t = i / rate;
    var env = Math.min(1, t * 6) * Math.min(1, (seconds - t) * 4);
    var ph = 2 * Math.PI * freq * t + wobble * Math.sin(2 * Math.PI * 0.8 * t);
    v.setUint8(44 + i, 128 + Math.round(Math.sin(ph) * env * 40));
  }
  var u8 = new Uint8Array(buf);
  var out = '';
  for (var j = 0; j < u8.length; j++) out += String.fromCharCode(u8[j]);
  return 'data:audio/wav;base64,' + btoa(out);
}

var TRACKS = [
  { id: 'demo-low', title: '示例音 · 低音', artist: 'NexlOS 示例', duration: 3, freq: 220, wobble: 0 },
  { id: 'demo-wobble', title: '示例音 · 颤动', artist: 'NexlOS 示例', duration: 3, freq: 330, wobble: 1.4 }
];

self.plugin = {
  search: function (query, page) {
    var q = String(query || '').toLowerCase();
    if (!q) return TRACKS.slice();
    return TRACKS.filter(function (t) {
      return t.title.toLowerCase().indexOf(q) >= 0 || ('示例 demo 测试').indexOf(q) >= 0;
    });
  },
  getMedia: function (id) {
    var hit = null;
    for (var i = 0; i < TRACKS.length; i++) if (TRACKS[i].id === id) hit = TRACKS[i];
    if (!hit) throw new Error('示例里没有 ' + id);
    return { url: tone(hit.duration, hit.freq, hit.wobble), mime: 'audio/wav' };
  }
};
